args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?personLabel ?birth ?death ( (YEAR(?death) - YEAR(?birth) - IF( (MONTH(?death) < MONTH(?birth)) || (MONTH(?death) = MONTH(?birth) && DAY(?death) < DAY(?birth)) , 1, 0) ) AS ?ageYears )
WHERE {
  VALUES ?person { dbr:Theodore_McMillian dbr:Hillel_Slovak }
  ?person dbo:birthDate ?birth .
  ?person dbo:deathDate ?death .
  OPTIONAL { ?person rdfs:label ?personLabel FILTER (lang(?personLabel) = "en") }
}
ORDER BY DESC(?ageYears)

